    ($json${"slug":"cyber-secrets-lisibles","title":"Audit : mot de passe et clé lisibles par tous les comptes","category":"cyber","difficulty":"beginner","ttlMinutes":40,"briefMd":"Un audit interne de **app04**, qui fait tourner la boutique en ligne (PHP-FPM sous le compte `www-data`),\nrelève trois points :\n\n1. le fichier de configuration de la boutique, qui contient le mot de passe de la base, est lisible par **tous** les comptes du serveur (dont `stagiaire`) ;\n2. une sauvegarde de la base traîne dans le dossier public du site, donc téléchargeable par n'importe qui ;\n3. la clé SSH privée du compte `deploy` est lisible par tous.\n\nCorrigez les trois points **sans casser la boutique**. Le code est dans `/var/www/boutique`.\n\n> Machine simulée : tapez `help` pour voir les commandes disponibles.","objectives":["Lire des droits Unix (ls -l, stat) : propriétaire, groupe, autres","Choisir le bon mode (640, 600) selon QUI doit lire le fichier","Vérifier qu’un service démarre encore après un durcissement"],"hints":[{"text":"ls -la /var/www/boutique : regardez les trois derniers caractères des droits de .env, ceux des « autres »."},{"text":"PHP-FPM lit .env sous le compte www-data. Le fichier appartient à root, groupe www-data : qui doit garder la lecture ?"},{"text":"chmod 640 garde la lecture au groupe www-data et la retire aux autres. Un chmod 600 la retirerait aussi à www-data."},{"text":"La sauvegarde est dans /var/www/boutique/public : supprimez-la. La clé privée doit être en 600. Redémarrez php8.2-fpm pour vérifier."}],"solutionMd":"**Constat** : `.env` est en `644` (`-rw-r--r--`) : propriétaire root, groupe www-data, et **lecture pour tous**.\nN'importe quel compte (ou un script compromis sous un autre compte) lit `DB_PASSWORD`. La sauvegarde SQL est sous\n`public/`, servi tel quel par nginx. La clé `id_ed25519` est en `644` : tout compte local peut se faire passer pour `deploy`.\n\n**Démarche** : `ls -la /var/www/boutique` ; `stat -c '%a %U:%G %n' /var/www/boutique/.env` ;\n`chmod 640 /var/www/boutique/.env` (root écrit, www-data lit, les autres rien) ;\n`rm /var/www/boutique/public/backup-2026-11-20.sql` ; `chmod 600 /home/deploy/.ssh/id_ed25519` ;\n`systemctl restart php8.2-fpm` pour vérifier que la boutique lit toujours sa configuration.\n\n**Le piège** : `chmod 600 .env` paraît plus sûr, mais le fichier appartient à root : www-data ne peut plus le lire\net PHP-FPM échoue au redémarrage (`Permission denied`). Le bon mode dépend de **qui** doit lire, pas d'un réflexe.\nPour la clé, c'est l'inverse : seul son propriétaire doit la lire, d'où `600` (ssh refuse d'ailleurs une clé trop ouverte).\n\n**Pour la suite** : le mot de passe a été exposé : faites-le changer côté base. Placez les sauvegardes hors du\ndossier servi par le web, et vérifiez régulièrement avec `find / -perm -o+r -name \"*.env\"` sur un vrai serveur.","simulation":{"machine":{"hostname":"app04","cwd":"/root","clock":"2026-11-24T09:40:00.000Z","nextPid":4100,"dirs":["/etc","/etc/ssh","/home","/root","/tmp","/usr","/var","/var/log","/var/www","/var/www/boutique","/var/www/boutique/public","/var/www/boutique/src","/home/deploy","/home/deploy/.ssh","/home/stagiaire","/etc/php","/run","/run/php"],"files":{"/var/log/syslog":{"size":2097152,"content":"Nov 24 08:58:02 app04 kernel: Linux version 6.1.0-27-amd64\nNov 24 08:58:05 app04 systemd[1]: Reached target multi-user.target.\nNov 24 08:59:10 app04 CRON[612]: (root) CMD (command -v debian-sa1 > /dev/null && debian-sa1 1 1)\n"},"/etc/group":{"size":86,"content":"root:x:0:\nadm:x:4:syslog\nwww-data:x:33:\nusers:x:100:\ndeploy:x:1001:\nstagiaire:x:1002:\n"},"/var/www/boutique/.env":{"size":180,"content":"APP_ENV=production\nAPP_URL=https://boutique.exemple.fr\nDB_HOST=10.0.3.20\nDB_NAME=boutique\nDB_USER=boutique\nDB_PASSWORD=Tr0ub4dor-boutique-2026\nMAIL_DSN=smtp://relais.exemple.fr:25\n","mode":"644","owner":"root","group":"www-data"},"/var/www/boutique/composer.json":{"size":412,"content":"{\n  \"name\": \"exemple/boutique\",\n  \"require\": { \"php\": \"^8.2\" }\n}\n"},"/var/www/boutique/src/Kernel.php":{"size":2380,"content":"<?php\n// Charge la configuration depuis ../.env\n"},"/var/www/boutique/public/index.php":{"size":640,"content":"<?php\nrequire __DIR__ . '/../src/Kernel.php';\n"},"/var/www/boutique/public/backup-2026-11-20.sql":{"size":50331648,"mode":"644","owner":"deploy","group":"deploy"},"/home/deploy/.ssh/id_ed25519":{"size":411,"content":"-----BEGIN OPENSSH PRIVATE KEY-----\n[clé privée simulée]\n-----END OPENSSH PRIVATE KEY-----\n","mode":"644","owner":"deploy","group":"deploy"},"/home/deploy/.ssh/id_ed25519.pub":{"size":98,"content":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExempleCleePublique deploy@app04\n","mode":"644","owner":"deploy","group":"deploy"},"/home/deploy/.ssh/authorized_keys":{"size":98,"content":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExempleCleePublique deploy@poste\n","mode":"600","owner":"deploy","group":"deploy"}},"mounts":[{"target":"/","device":"/dev/sda1","sizeBytes":32212254720,"baseUsedBytes":6657199309}],"services":{"ssh":{"description":"OpenBSD Secure Shell server","active":"active","enabled":true,"process":"sshd","pid":702,"ports":[22],"needsFiles":["/etc/ssh/sshd_config"],"journal":["nov. 24 08:58:04 app04 systemd[1]: Started ssh.service - OpenBSD Secure Shell server."]},"nginx":{"description":"A high performance web server and a reverse proxy server","active":"active","enabled":true,"process":"nginx","pid":731,"ports":[80,443],"journal":["nov. 24 08:58:05 app04 systemd[1]: Started nginx.service - A high performance web server and a reverse proxy server."]},"php8.2-fpm":{"description":"The PHP 8.2 FastCGI Process Manager","active":"active","enabled":true,"process":"php-fpm","pid":744,"ports":[9000],"user":"www-data","needsFiles":["/var/www/boutique/.env"],"journal":["nov. 24 08:58:06 app04 systemd[1]: Started php8.2-fpm.service - The PHP 8.2 FastCGI Process Manager."]}}},"validators":[{"description":"La boutique (www-data) peut lire sa configuration","check":{"kind":"file_readable_by","path":"/var/www/boutique/.env","user":"www-data","expected":true}},{"description":"Les autres comptes ne lisent plus la configuration","check":{"kind":"file_readable_by","path":"/var/www/boutique/.env","user":"stagiaire","expected":false}},{"description":"La sauvegarde n’est plus dans le dossier public","check":{"kind":"path_exists","path":"/var/www/boutique/public/backup-2026-11-20.sql","expected":false}},{"description":"La clé privée n’est accessible qu’à son propriétaire","check":{"kind":"file_mode_at_most","path":"/home/deploy/.ssh/id_ed25519","mode":"600"}},{"description":"Le compte deploy peut toujours utiliser sa clé","check":{"kind":"file_readable_by","path":"/home/deploy/.ssh/id_ed25519","user":"deploy","expected":true}},{"description":"PHP-FPM tourne","check":{"kind":"service_active","service":"php8.2-fpm"}}],"walkthrough":["ls -la /var/www/boutique","stat -c '%a %U:%G %n' /var/www/boutique/.env","chmod 640 /var/www/boutique/.env","ls -l /var/www/boutique/public","rm /var/www/boutique/public/backup-2026-11-20.sql","ls -l /home/deploy/.ssh","chmod 600 /home/deploy/.ssh/id_ed25519","systemctl restart php8.2-fpm","systemctl status php8.2-fpm"]}}$json$::jsonb)
  ) AS v(l)
